<?php
declare(strict_types=1);

function nzd_find_post(string $id): ?array {foreach(nzc_db_read()['posts']as$p)if(($p['id']??'')===$id)return$p;return null;}
function nzd_img(array $p): string {return!empty($p['images'][0])?'/marketplace-uploads/'.rawurlencode(basename((string)$p['images'][0])):'/niazestan-icon.svg';}
function nzd_replace_main(string $html,string $main): string {foreach(['/\<main class="main"\>.*?\<\/main\>/su','/\<main class="detail"\>.*?\<\/main\>/su','/\<div class="empty"\>آگهی پیدا نشد.*?\<\/div\>/su']as$pattern)if(preg_match($pattern,$html))return preg_replace($pattern,$main,$html,1)??$html;return str_replace('<nav class="mobile-nav">',$main.'<nav class="mobile-nav">',$html);}
function nzd_admin_pending_html(array $p,array $user): string {
    $csrf=nzc_e($_SESSION['csrf']??'');$mod=(array)($p['moderation']??[]);$reasons=(array)($mod['reasons']??[]);$html='<main class="page nzd-admin-detail"><a class="btn ghost" href="/nz?page=admin">بازگشت به مدیریت</a><div class="surface" style="margin-top:12px">';if(!empty($mod['flagged']))$html.='<div style="background:#fff0ee;border:2px solid #d92d20;border-radius:14px;padding:12px;margin-bottom:14px"><b style="color:#b42318">⚠ بررسی فوری با اولویت بالا</b><div style="margin-top:7px;line-height:2">'.nzc_e(implode('، ',$reasons)).'</div><small>امتیاز ریسک: '.(int)($mod['score']??0).'</small></div>';$html.='<h1>'.nzc_e($p['title']??'آگهی').'</h1><div class="subtle">'.nzc_e(($p['province']??'').'، '.($p['city']??'').'، '.($p['district']??'')).'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin:16px 0">';foreach(array_slice((array)($p['images']??[]),0,5)as$img)$html.='<img src="/marketplace-uploads/'.rawurlencode(basename((string)$img)).'" alt="" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px">';$html.='</div><div class="surface" style="padding:14px;margin:12px 0"><h3>توضیحات</h3><div class="description">'.nl2br(nzc_e($p['description']??'')).'</div></div>';if(!empty($p['attributes'])){$html.='<div class="specs">';foreach($p['attributes']as$k=>$v)$html.='<div class="spec"><span>'.nzc_e($k).'</span><b>'.nzc_e($v).'</b></div>';$html.='</div>';}if(!empty($mod['ocr_excerpt']))$html.='<div style="margin:12px 0;background:#fff8e8;border:1px solid #f2d69b;border-radius:12px;padding:12px"><b>متن تشخیص‌داده‌شده داخل تصویر</b><div style="margin-top:7px;line-height:1.9">'.nzc_e($mod['ocr_excerpt']).'</div></div>';$html.='<div class="nzc-admin-actions" style="margin-top:18px"><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="approve_post"><input type="hidden" name="post_id" value="'.nzc_e($p['id']??'').'"><button class="btn primary">تأیید و انتشار</button></form><form method="post" class="nzc-reject"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="reject_post"><input type="hidden" name="post_id" value="'.nzc_e($p['id']??'').'"><input name="reason" maxlength="600" placeholder="دلیل رد آگهی"><button class="btn danger">رد آگهی</button></form></div></div></main>';return$html;
}
function nzd_owner_private_html(array $p): string {return'<main class="page page-narrow"><div class="surface"><h1>'.nzc_e($p['title']??'آگهی').'</h1><p class="lead">وضعیت: <b>'.nzc_e(nzc_status_fa((string)($p['status']??''))).'</b></p><p>این آگهی در حال حاضر برای سایر کاربران نمایش داده نمی‌شود.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="btn ghost" href="/nz?page=myposts">آگهی‌های من</a><a class="btn primary" href="/nz?page=edit&id='.rawurlencode((string)$p['id']).'">ویرایش</a></div></div></main>';}
function nzd_hidden_html(): string {http_response_code(404);return'<main class="page page-narrow"><div class="surface"><h1>آگهی در دسترس نیست</h1><p class="lead">این آگهی حذف، منقضی، فروخته یا در حال بررسی است.</p><a class="btn" href="/nz">بازگشت به نیازستان</a></div></main>';}
function nzd_enhance(string $html): string {
    $id=(string)($_GET['id']??'');if($id==='')return$html;$db=nzc_db_read();$p=null;foreach($db['posts']as$row)if(($row['id']??'')===$id){$p=$row;break;}if(!$p)return$html;$user=nzc_current_user($db);$status=(string)($p['status']??'');
    if($status!=='published'){if($user&&nzc_is_admin($user))return nzd_replace_main($html,nzd_admin_pending_html($p,$user));if($user&&($p['user_id']??'')===($user['id']??''))return nzd_replace_main($html,nzd_owner_private_html($p));return nzd_replace_main($html,nzd_hidden_html());}
    $owner=null;foreach($db['users']as$u)if(($u['id']??'')===($p['user_id']??'')){$owner=$u;break;}$active=0;if($owner)foreach($db['posts']as$x)if(($x['user_id']??'')===($owner['id']??'')&&($x['status']??'')==='published')$active++;
    $joined=$owner?date('Y/m',strtotime($owner['created_at']??'now')):'-';$seller='<div class="surface nzd-seller" style="margin-top:14px"><h3 style="margin-top:0">فروشنده</h3><div style="display:flex;justify-content:space-between;gap:10px"><div><b>'.nzc_e($owner['name']??'کاربر نیازستان').'</b><div class="subtle" style="margin-top:5px">عضو از '.nzc_e($joined).' · '.$active.' آگهی فعال'.(!empty($owner['phone'])?' · شماره تأییدشده':'').'</div></div><button type="button" class="btn ghost" onclick="navigator.share?navigator.share({title:document.title,url:location.href}):navigator.clipboard.writeText(location.href)">اشتراک‌گذاری</button></div></div>';
    $safety='<div class="surface" style="margin-top:14px;background:#fafafa"><h3 style="margin-top:0">نکات معامله امن</h3><div class="subtle" style="line-height:2">قبل از پرداخت، کالا و مدارک را حضوری بررسی کنید. اطلاعات بانکی، رمز یا کد ورود را در چت ارسال نکنید و موارد مشکوک را گزارش دهید.</div></div>';$html=str_replace('</section></main>',$seller.$safety.'</section></main>',$html);
    $similar=array_values(array_filter($db['posts'],fn($x)=>($x['status']??'')==='published'&&($x['id']??'')!==$id&&(($x['subcategory']??'')===($p['subcategory']??'')||($x['city']??'')===($p['city']??''))));usort($similar,fn($a,$b)=>strtotime($b['created_at']??'now')<=>strtotime($a['created_at']??'now'));$similar=array_slice($similar,0,4);if($similar){$cards='<section class="page" style="padding-top:0"><div class="surface"><h2>آگهی‌های مشابه</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">';foreach($similar as$x)$cards.='<a href="/nz?id='.rawurlencode((string)$x['id']).'" style="text-decoration:none;border:1px solid #eee;border-radius:13px;overflow:hidden"><img src="'.nzc_e(nzd_img($x)).'" style="width:100%;aspect-ratio:1.3;object-fit:cover"><div style="padding:9px"><b>'.nzc_e($x['title']??'آگهی').'</b><div class="subtle" style="margin-top:5px">'.nzc_e($x['city']??'').'</div></div></a>';$cards.='</div></div></section>';$html=str_replace('<nav class="mobile-nav">',$cards.'<nav class="mobile-nav">',$html);}return$html;
}
